                counsel_idxs.append(i)

        candidate_idxs = []
        if counsel_idxs:
            for c_idx in counsel_idxs:
                end_idx = len(lines)
                for j in range(c_idx + 1, len(lines)):
                    text = norm(lines[j].get("text", ""))
                    if text.upper() in {"OPINION", "SUMMARY", "ORDER"}:
