            return [result]

        # Last-resort fallback: use the appellant caption block itself.
        label_idx = None
        for i, line in enumerate(lines[:150]):
            text = norm(line.get("text", ""))
            lowered = text.lower()
            if not text or "for" in lowered and lowered.endswith("for"):
