import re


_COUNSEL_HEADING_RE = re.compile(r"^\s*COUNSEL\s*$", re.IGNORECASE)
_APPELLEE_BLOCK_RE = re.compile(
    r"\bfor\s+"
    r"(?:Plaintiff|Plaintiffs|Defendant|Defendants|Respondent|Respondents|"
    r"Intervenor(?:-Defendant|-Respondent)?|Appellee|Appellees)"
    r"[^.\n]*\bAppellee(?:s)?\b",
    re.IGNORECASE,
)
_COUNSEL_LIST_HEADING_RE = re.compile(
    r"^\s*Counsel for\s+.*Appellee(?:s)?\s*:?\s*(.*)$", re.IGNORECASE
)
_MAJOR_STOP_HEADING_RE = re.compile(
    r"^\s*(?:OPINION|ORDER|SUMMARY|JUDGMENT|MEMORANDUM|BACKGROUND|INTRODUCTION|"
    r"DISCUSSION|CONCLUSION|PER CURIAM)\b",
    re.IGNORECASE,
)
_ORGANIZATION_WORD_RE = re.compile(
    r"\b(?:LLP|LLC|P\.C\.|PC|INC\.?|CORPORATION|COMPANY|DEPARTMENT|OFFICE|"
    r"UNIVERSITY|ASSOCIATION|GROUP|SERVICES|ATTORNEY|ATTORNEYS|COUNSEL|"
    r"LAWYERS|PARTNERS|BUDD|CLINIC|FOUNDATION|TRUST|COMMITTEE|AGENCY|"
    r"STATES ATTORNEY|UNITED STATES ATTORNEY)\b",
    re.IGNORECASE,
)


def _norm(text: str) -> str:
    return " ".join((text or "").split())


def _clean_name(text: str) -> str | None:
    text = _norm(text)
    if not text:
        return None
    # Remove a leading counsel-list label if one is present.
    text = re.sub(r"^\s*Counsel for\s+.*?Appellee(?:s)?\s*:?\s*", "", text, flags=re.IGNORECASE)
    text = text.strip()
    if not text:
        return None
    # The first attorney is typically the first comma-delimited token.
    candidate = text.split(",", 1)[0].strip()
    if " and " in candidate:
        candidate = candidate.split(" and ", 1)[0].strip()
    candidate = re.sub(r"\s*\([^)]*\)\s*$", "", candidate).strip(" ,;")
    candidate = candidate.strip()
    if not candidate or len(candidate) < 2:
        return None
    if ":" in candidate or "@" in candidate or _ORGANIZATION_WORD_RE.search(candidate):
        return None
    if len(candidate.split()) < 2:
        return None
    return candidate


def _line_dicts(doc: dict) -> list[dict]:
    lines = doc.get("lines") or []
    if lines:
        return lines
    text = doc.get("text") or ""
    out = []
    for i, raw in enumerate(text.splitlines(), start=1):
        out.append({"page_no": None, "line_no": i, "text": raw})
    return out


def _span_from_lines(lines: list[dict], start: int, end: int, text: str) -> dict:
    span = {"text": text}
    if 0 <= start < len(lines):
        page_no = lines[start].get("page_no")
        line_no = lines[start].get("line_no")
        if page_no is not None:
            span["page_no"] = page_no
        if line_no is not None:
            span["line_no"] = line_no
    return span


def _is_party_end(text: str) -> bool:
    compact = re.sub(r"\s+", "", text or "").lower()
    party_tokens = (
        "appellant",
        "appellants",
        "petitioner",
        "petitioners",
        "respondent",
        "respondents",
        "appellee",
        "appellees",
        "amicus",
        "amici",
        "intervenor",
        "plaintiff",
        "defendant",
    )
    if "for" in compact and any(token in compact for token in party_tokens):
        return True
    if len(compact) <= 60 and compact.endswith(".") and not any(ch in compact for ch in ",;:@") and any(
        token in compact for token in party_tokens
    ):
        return True
    return False


def _extract_from_standard_counsel(lines: list[dict]) -> list[dict]:
    counsel_idx = None
    for i, line in enumerate(lines):
        if _COUNSEL_HEADING_RE.match(_norm(line.get("text", ""))):
            counsel_idx = i
            break
    if counsel_idx is None:
        return []

    for end in range(counsel_idx + 1, len(lines)):
        raw = _norm(lines[end].get("text", ""))
        if not raw:
            continue
        if _MAJOR_STOP_HEADING_RE.match(raw):
            break

        window_start = max(counsel_idx + 1, end - 2)
        window = " ".join(
            _norm(lines[j].get("text", "")) for j in range(window_start, end + 1) if _norm(lines[j].get("text", ""))
        )
        compact = re.sub(r"\s+", "", window).lower()
        if "for" not in compact or "appellee" not in compact:
            continue

        start = end
        while start > counsel_idx + 1:
            prev = _norm(lines[start - 1].get("text", ""))
            if not prev:
                start -= 1
                continue
            if _MAJOR_STOP_HEADING_RE.match(prev):
                break
            if _is_party_end(prev):
                break
            start -= 1

        block = " ".join(
            _norm(lines[j].get("text", "")) for j in range(start, end + 1) if _norm(lines[j].get("text", ""))
        )
        name = _clean_name(block)
        if name:
            return [_span_from_lines(lines, start, end, name)]

    return []


def _extract_from_counsel_list(lines: list[dict]) -> list[dict]:
    for i, line in enumerate(lines):
        raw = line.get("text", "") or ""
        m = _COUNSEL_LIST_HEADING_RE.match(raw)
        if not m:
            continue
        tail = _norm(m.group(1))
        if tail:
            name = _clean_name(tail)
            if name:
                return [_span_from_lines(lines, i, i, name)]

        for j in range(i + 1, len(lines)):
            candidate = _norm(lines[j].get("text", ""))
            if not candidate:
                continue
            if candidate.startswith("*") or candidate.startswith("This summary constitutes"):
                continue
            if candidate.endswith(":"):
                continue
            if candidate and not candidate.lower().startswith("counsel for") and len(candidate) < 120:
                name = _clean_name(candidate)
                if name:
                    return [_span_from_lines(lines, j, j, name)]
            if _MAJOR_STOP_HEADING_RE.match(candidate):
                break
    return []


def rule_first_listed_attorney_representing_appellees(doc: dict) -> list[dict]:
    try:
        lines = _line_dicts(doc)
        spans = _extract_from_standard_counsel(lines)
        if spans:
            return spans
        return _extract_from_counsel_list(lines)
    except Exception:
        return []

from __future__ import annotations
import re


_COUNSEL_HEAD_RE = re.compile(
    r"(?:^|\n)\s*(?:COUNSEL|ATTORNEYS?)\s*(?:\n|$)",
    re.IGNORECASE,
)
_APPELLANT_TAG_RE = re.compile(
    r"(?:\bfor\b(?:[ \t]*\n[ \t]*|[ \t]+)?)?(?:"
    r"Plaintiffs?[\s\-]*Appellants?|"
    r"Defendants?[\s\-]*Appellants?|"
    r"Petitioners?[\s\-]*Appellants?|"
    r"Respondents?[\s\-]*Appellants?|"
    r"Appellants?"
    r")\b\.?",
    re.IGNORECASE,
)
_SIDE_TAG_RE = re.compile(
    r"(?:\bfor\b(?:[ \t]*\n[ \t]*|[ \t]+)?)?(?:"
    r"Plaintiffs?[\s\-]*Appellants?|"
    r"Plaintiffs?[\s\-]*Appellees?|"
    r"Defendants?[\s\-]*Appellants?|"
    r"Defendants?[\s\-]*Appellees?|"
    r"Petitioners?[\s\-]*Appellants?|"
    r"Petitioners?[\s\-]*Appellees?|"
    r"Respondents?[\s\-]*Appellants?|"
    r"Respondents?[\s\-]*Appellees?|"
    r"Appellants?|"
    r"Appellees?"
    r")\b\.?",
    re.IGNORECASE,
)


def rule_first_listed_attorney_appellant(doc: dict) -> list[dict]:
    try:
        def norm(text: str) -> str:
            return re.sub(r"\s+", " ", (text or "")).strip()

        def first_attorney_from_block(block: str) -> str:
            text = norm(block)
            if not text:
                return ""

            text = re.sub(r"^\s*(?:and\s+)?", "", text, flags=re.IGNORECASE)
            text = text.split(";", 1)[0].strip()
            text = text.split(",", 1)[0].strip()
            text = re.split(r"\s+\band\b\s+", text, 1, flags=re.IGNORECASE)[0].strip()
            text = re.sub(r"\s*\((?:argued|lead|co[- ]?counsel|on brief|oral argument)\)\s*$", "", text, flags=re.IGNORECASE)
            text = re.sub(r"\s*\([^)]*\)\s*$", "", text).strip()
            text = re.sub(r"\s{2,}", " ", text).strip(" ,;:")
            if not text:
                return ""

            # If the extracted prefix still looks like an office or firm, keep it
            # only when there is no attorney-like name pattern to the left.
            return text

        def make_span(text: str, src: dict | None = None) -> dict:
            span = {"text": norm(text)}
            if src:
                for key in ("page_no", "paragraph_no", "line_no"):
                    if key in src:
                        span[key] = src[key]
            return span

        candidates: list[tuple[int, int, int, str, dict | None]] = []

        for source_key in ("pages", "paragraphs", "lines"):
            items = [item for item in (doc.get(source_key) or []) if isinstance(item, dict)]
            for idx, item in enumerate(items):
                raw_text = item.get("text") or ""
                text = norm(raw_text)
                if not text or "appellant" not in text.lower():
                    continue
                if not _COUNSEL_HEAD_RE.search(raw_text):
                    continue
                head = _COUNSEL_HEAD_RE.search(raw_text)
                search_start = head.end() if head else 0
                match = _APPELLANT_TAG_RE.search(raw_text, search_start)
                if match:
                    section = raw_text[search_start: match.start()]
                    if not section:
                        continue
                    prev = None
                    for side_match in _SIDE_TAG_RE.finditer(section):
                        prev = side_match
                    block = section[prev.end() :] if prev else section
                    block = block.strip()
                    if block:
                        candidates.append((0 if prev else 1, len(block), idx, block, item))

        raw_text = doc.get("text") or ""
        if isinstance(raw_text, str) and raw_text:
            head = _COUNSEL_HEAD_RE.search(raw_text)
            if head:
                search_start = head.end()
                match = _APPELLANT_TAG_RE.search(raw_text, search_start)
                if match:
                    section = raw_text[search_start: match.start()]
                    if section:
                        prev = None
                        for side_match in _SIDE_TAG_RE.finditer(section):
                            prev = side_match
                        block = section[prev.end() :] if prev else section
                        block = block.strip()
                        if block:
                            candidates.append((0 if prev else 1, len(block), 10000, block, None))

        if not candidates:
            for source_key in ("pages", "paragraphs", "lines"):
                items = [item for item in (doc.get(source_key) or []) if isinstance(item, dict)]
                combined = "\n".join((item.get("text") or "") for item in items if item.get("text"))
                if not combined:
                    continue
                head = _COUNSEL_HEAD_RE.search(combined)
                if not head:
                    continue
                search_start = head.end()
                match = _APPELLANT_TAG_RE.search(combined, search_start)
                if not match:
                    continue
                section = combined[search_start: match.start()]
                if not section:
                    continue
                prev = None
                for side_match in _SIDE_TAG_RE.finditer(section):
                    prev = side_match
                block = section[prev.end() :] if prev else section
                block = block.strip()
                if block:
                    candidates.append((0 if prev else 1, len(block), 20000, block, None))
                    break

        if not candidates:
            return []

        # Prefer the shortest prefix among plausible counsel blocks.
        candidates.sort(key=lambda item: (item[0], item[1], item[2]))
        for _, _, _, prefix, src in candidates:
            first = first_attorney_from_block(prefix)
            if first:
                return [make_span(first, src)]

        return []
    except Exception:
        return []

